foreignObject.script:
      // Typing effect logic
      const text1 = "I'm a Computer Science student at MMMUT and a Data Science student at IIT Madras. I love building products, exploring AI, designing systems, and creating communities that move forward together.";
      const text2 = "My journey is driven by curiosity, consistency, and the belief that technology should empower people to build a better tomorrow.";

      const p1 = document.getElementById('typing-text-1');
      const p2 = document.getElementById('typing-text-2');

      const cursor = '<span class="typing-cursor"></span>';

      let i = 0;
      let j = 0;

      function typeText1() {
          if (i < text1.length) {
              p1.innerHTML = text1.substring(0, i + 1) + cursor;
              i++;
              // Randomizing typing speed to make it look natural
              setTimeout(typeText1, Math.random() * 40 + 30);
          } else {
              p1.innerHTML = text1; // Remove cursor
              p2.innerHTML = cursor;
              setTimeout(typeText2, 500); // pause
          }
      }

      function typeText2() {
          if (j < text2.length) {
              p2.innerHTML = text2.substring(0, j + 1) + cursor;
              j++;
              setTimeout(typeText2, Math.random() * 40 + 30);
          }
      }

      // Animated Counter for Stats
      function animateCounters() {
          const counters = document.querySelectorAll('.anim-counter');
          counters.forEach(counter => {
              const target = +counter.getAttribute('data-val');
              const duration = 2000; // 2 seconds
              const increment = target / (duration / 16); 
              let current = 0;

              const updateCounter = () => {
                  current += increment;
                  if (current < target) {
                      counter.innerText = Math.ceil(current);
                      requestAnimationFrame(updateCounter);
                  } else {
                      counter.innerText = target;
                  }
              };
              updateCounter();
          });
      }

      document.addEventListener('DOMContentLoaded', () => {
          typeText1();
          animateCounters();
      });

      // Fetch dynamic logic (progressive enhancement)
      document.addEventListener('DOMContentLoaded', async () => {
          const USERNAME = 'HeyItsSuyash';
          try {
              const reposRes = await fetch(`https://api.github.com/users/${USERNAME}/repos?sort=updated&per_page=5`);
              if (reposRes.ok) {
                  const repos = await reposRes.json();
                  const container = document.getElementById('repos-container');
                  if(repos.length > 0) {
                      container.innerHTML = ''; 
                      repos.forEach(repo => {
                          const langColors = { TypeScript: '#3178c6', JavaScript: '#f1e05a', Python: '#3572A5', Java: '#b07219' };
                          const langColor = langColors[repo.language] || '#8cc3a9';

                          container.innerHTML += `





                                  ${repo.name}


${repo.description || 'No description provided for this repository.'}


                                  ${repo.language ? `<span class="tag" style="border-left: 3px solid ${langColor};">${repo.language}</span>` : ''}
                                  <span class="tag">⭐ ${repo.stargazers_count}</span>

                              <a href="${repo.html_url}" target="_blank" class="clay-btn card-btn">View Repository</a>
                          `;
                      });

                      // Inject the "View More" card dynamically at the end
                      container.innerHTML += `



View More Projects

                      `;
                  }
              }

              const profileRes = await fetch(`https://api.github.com/users/${USERNAME}`);
              if (profileRes.ok) {
                  const profile = await profileRes.json();
                  const repoEl = document.getElementById('stat-repos');
                  const followerEl = document.getElementById('stat-followers');
                  repoEl.setAttribute('data-val', profile.public_repos);
                  followerEl.setAttribute('data-val', profile.followers);
                  // Trigger re-animation with dynamic values
                  animateCounters();
              }
          } catch(e) {
              console.error('Dynamic fetch failed', e);
          }
      });
